#!/usr/bin/env node
/* Checks for the 動詞活用ドリル bank (generated by tools/gen_katsuyo.cjs). */
const fs = require('fs');
const SIMPLIFIED = new Set([...'间问际实验证议务运过见产车单压长关头发汉语纪给结经济应该两动员术业样齐认产权让']);
const forms = ['masu', 'nai', 'te', 'ta', 'ishi', 'meirei', 'katei', 'kanou', 'ukemi', 'shieki', 'shiekiukemi'];
let bad = 0, total = 0; const hits = [];
const flag = (where, s) => { if (typeof s !== 'string') return; const b = [...s].filter(c => SIMPLIFIED.has(c)); if (b.length) hits.push(`  ${where}  ${b.join('')}  →  ${s.slice(0, 50)}`); };
for (const f of forms) {
  const arr = eval(fs.readFileSync(`src/doushi-drill/data/${f}.js`, 'utf8').replace(new RegExp(`^[\\s\\S]*?const F_${f} =`), ''));
  const g = {}; arr.forEach(q => g[q[0]] = (g[q[0]] || 0) + 1);
  const shape = arr.filter(q => q.length !== 7 || q[2].length !== 4 || q[2].some(o => !o)).length;
  const dup = arr.filter(q => new Set(q[2]).size !== 4).length;
  const sorted = arr.every((q, i) => i === 0 || q[0] >= arr[i - 1][0]);
  arr.forEach((q, i) => { flag(`${f}#${i + 1} stem`, q[1]); q[2].forEach(o => flag(`${f}#${i + 1} option`, o)); });
  total += arr.length;
  console.log(`  katsuyo/${f}: ${arr.length} items, per group ${[1, 2, 3, 4].map(l => g[l] || 0).join('/')}, bad shape ${shape}, dup options ${dup}, grouped ${sorted}`);
  if (arr.length < 250 || shape || dup || !sorted) bad = 1;
}
console.log(`  katsuyo: ${total} questions`);
// spot checks of known traps
const te = eval(fs.readFileSync('src/doushi-drill/data/te.js', 'utf8').replace(/^[\s\S]*?const F_te =/, ''));
const q = w => te.find(r => r[4] === w);
const expect = [['行く', '行って（いって）'], ['書く', '書いて（かいて）'], ['泳ぐ', '泳いで（およいで）'], ['話す', '話して（はなして）'], ['帰る', '帰って（かえって）'], ['食べる', '食べて（たべて）'], ['来る', '来て（きて）'], ['勉強する', '勉強して（べんきょうして）']];
for (const [w, c] of expect) { const r = q(w); if (!r || r[2][0] !== c) { console.log(`  TRAP FAIL te形 ${w}: ${r && r[2][0]}`); bad = 1; } }
const su = eval(fs.readFileSync('src/doushi-drill/data/shiekiukemi.js', 'utf8').replace(/^[\s\S]*?const F_shiekiukemi =/, ''));
for (const [w, c] of [['話す', '話させられる（はなさせられる）'], ['書く', '書かされる（かかされる）'], ['食べる', '食べさせられる（たべさせられる）']]) { const r = su.find(x => x[4] === w); if (!r || r[2][0] !== c) { console.log(`  TRAP FAIL 使役受身 ${w}: ${r && r[2][0]}`); bad = 1; } }
if (hits.length) { console.log('MIXED SCRIPT in Japanese fields:'); console.log(hits.join('\n')); bad = 1; } else console.log('  katsuyo mixed-script scan: clean');
process.exit(bad);
